def choose_move(observation):
    # Defensive defaults
    x = observation.get("agent_x", 0)
    y = observation.get("agent_y", 0)

    # Initialize move to stay in place
    dx = 0
    dy = 0

    # Resource_collection: move toward nearest resource if available
    resources = observation.get("resources", [])
    if resources:
        # Find closest resource
        best = None
        best_dist = float("inf")
        for r in resources:
            rx, ry = r.get("x", 0), r.get("y", 0)
            dist = abs(rx - x) + abs(ry - y)
            if dist < best_dist:
                best_dist = dist
                best = (rx, ry)
        if best is not None:
            rx, ry = best
            if rx > x:
                dx = 1
            elif rx < x:
                dx = -1
            if ry > y:
                dy = 1
            elif ry < y:
                dy = -1
            # If already aligned on one axis, the other may stay 0

    # If no resources or to add robustness, pursue evasion if an evader nearby
    if dx == 0 and dy == 0:
        # Look for evaders
        evaders = observation.get("evaders", [])
        if evaders:
            best_e = None
            best_dist = float("inf")
            for e in evaders:
                ex = e.get("x", 0)
                ey = e.get("y", 0)
                dist = abs(ex - x) + abs(ey - y)
                if dist < best_dist:
                    best_dist = dist
                    best_e = (ex, ey)
            if best_e is not None:
                ex, ey = best_e
                if ex > x:
                    dx = 1
                elif ex < x:
                    dx = -1
                if ey > y:
                    dy = 1
                elif ey < y:
                    dy = -1

    # Territory control: if no directive yet, try to move toward owned area
    if dx == 0 and dy == 0:
        owned = observation.get("owned", [])
        target_tile = None
        if isinstance(owned, list) and owned:
            # Prefer the closest owned tile
            best_o = None
            best_dist = float("inf")
            for t in owned:
                tx = t.get("x", 0)
                ty = t.get("y", 0)
                dist = abs(tx - x) + abs(ty - y)
                if dist < best_dist:
                    best_dist = dist
                    best_o = (tx, ty)
            if best_o is not None:
                target_tile = best_o
        if target_tile:
            tx, ty = target_tile
            if tx > x:
                dx = 1
            elif tx < x:
                dx = -1
            if ty > y:
                dy = 1
            elif ty < y:
                dy = -1

    # Clamp to valid moves [-1,0,1]
    if dx not in (-1, 0, 1):
        dx = 0
    if dy not in (-1, 0, 1):
        dy = 0

    return [dx, dy]

